1	import { test, before, after } from 'node:test';
2	import assert from 'node:assert/strict';
3	import vm from 'node:vm';
4	import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';
5	
6	// 这些测试不在浏览器里跑，而是启动真实服务、GET / 取出页面里的内联脚本原文，
7	// 再放入带极简 DOM / 可控 fetch 的 vm 沙箱执行。被测脚本与线上页面逐字一致，
8	// 同时每个请求的成功、失败、返回先后都可以由测试精确控制。
9	
10	let server: StartedServer;
11	let pageScript: string;
12	
13	before(async () => {
14	  server = await startServer();
15	  const res = await fetch(`${server.origin}/`);
16	  assert.equal(res.status, 200);
17	  const html = await res.text();
18	  const start = html.indexOf('<script>');
19	  const end = html.lastIndexOf('</script>');
20	  assert.notEqual(start, -1);
21	  assert.ok(end > start);
22	  pageScript = html.slice(start + '<script>'.length, end);
23	});
24	
25	after(async () => {
26	  await server.stop();
27	  removeDataDir(server);
28	});
29	
30	interface El {
31	  tagName: string;
32	  className: string;
33	  hidden: boolean;
34	  value: string;
35	  dateTime: string;
36	  children: El[];
37	  text: string | null;
38	  textContent: string;
39	  // 警戒标记：页面一旦通过 innerHTML 渲染内容即为 true（纯文本展示不允许走 innerHTML）
40	  innerHTMLAssigned: boolean;
41	  listeners: Record<string, Array<(event: unknown) => unknown>>;
42	  append(...nodes: El[]): void;
43	  replaceChildren(...nodes: El[]): void;
44	  addEventListener(type: string, fn: (event: unknown) => unknown): void;
45	  reset(): void;
46	}
47	
48	function makeElement(tag: string): El {
49	  const node = {
50	    tagName: tag.toUpperCase(),
51	    className: '',
52	    hidden: false,
53	    value: '',
54	    dateTime: '',
55	    children: [],
56	    text: null as string | null,
57	    innerHTMLAssigned: false,
58	    listeners: {} as Record<string, Array<(event: unknown) => unknown>>,
59	    append(...nodes: El[]): void {
60	      this.children.push(...nodes);
61	    },
62	    replaceChildren(...nodes: El[]): void {
63	      this.children = [...nodes];
64	    },
65	    addEventListener(type: string, fn: (event: unknown) => unknown): void {
66	      (this.listeners[type] ??= []).push(fn);
67	    },
68	    reset(): void {},
69	  };
70	  Object.defineProperty(node, 'textContent', {
71	    get(this: any): string {
72	      return this.text !== null ? this.text : this.children.map((c: El) => c.textContent).join('');
73	    },
74	    set(this: any, value: unknown): void {
75	      this.text = String(value);
76	    },
77	  });
78	  // innerHTML 只记录不解析：意见内容若改走 innerHTML 渲染，textContent 断言会失败，
79	  // innerHTMLAssigned 标记则给出更直接的原因
80	  Object.defineProperty(node, 'innerHTML', {
81	    get(): string {
82	      return '';
83	    },
84	    set(this: any, value: unknown): void {
85	      this.innerHTMLAssigned = true;
86	    },
87	  });
88	  return node as El;
89	}
90	
91	interface Gate {
92	  promise: Promise<unknown>;
93	  resolve: (value: unknown) => void;
94	  reject: (error: Error) => void;
95	}
96	
97	function gate(): Gate {
98	  let resolve!: (value: unknown) => void;
99	  let reject!: (error: Error) => void;
100	  const promise = new Promise<unknown>((res, rej) => {
101	    resolve = res;
102	    reject = rej;
103	  });
104	  return { promise, resolve, reject };
105	}
106	
107	function jsonResponse(status: number, body: unknown): any {
108	  return {
109	    ok: status >= 200 && status < 300,
110	    status,
111	    json: async () => body,
112	  };
