  h.gets[0].resolve(jsonResponse(200, { ideas: [existing] }));
  await flush();

  // 标题带首尾空白：仍遵循现有处理（保存与展示去空白后的结果），不为这些片段另设规则
  const typedTitle = '  ' + MARKUP_TITLE + '  ';
