  // 接口实际返回的记录：标题已去首尾空白，详细说明与使用场景逐字保留
  const saved = makeIdea({ id: 'a', title: MARKUP_TITLE, description: MARKUP_DESCRIPTION, scenario: MARKUP_SCENARIO });
  h.posts[0].resolve(jsonResponse(201, { idea: saved }));
