    scenario: '',
  });
  // 含 "abc" 但不含逐字 "a.c"：若关键词被当成正则，"a.c" 会误命中这条
  const dotTrick = makeIdea({ id: 'r3', title: '字母连写', description: '比如 abc 这样的连写', scenario: '' });
  const markup = makeIdea({
    id: 'r2',
