  await flush();

  // 正则元字符按普通字符："a.c" 只能逐字命中，不能像正则那样匹配 "abc"
  h.search('a.c');
  assert.deepEqual(h.titles(), ['普通标题']);
  h.search('[abc]');
  assert.deepEqual(h.titles(), ['普通标题']);
  h.search('^start$');
  assert.deepEqual(h.titles(), ['普通标题']);
  h.search('x+y*?');
  assert.deepEqual(h.titles(), ['普通标题']);
  // 改成逐字片段后，"abc" 记录可以正常命中
  h.search('abc');
  assert.deepEqual(h.titles(), ['普通标题', '字母连写']);

  // 尖括号与标点同样按普通文字逐字命中
