  assert.deepEqual(h.titles(), ['香蕉意见']);
  h.clearSearch();
  assert.equal(h.els['f-search'].value, '');
  assert.deepEqual(h.titles(), ['苹果意见', '香蕉意见', '橘子意见']);
});

test('搜索：首次加载成功且完整列表为空时仍提示“还没有意见记录”，不把它说成没有找到', async () => {
